type Order = { id: string; status: 'paid' | 'pending' | 'refunded'; amountCents: number };
function summarizeOrders(orders: readonly Order[]): { paidCount: number; netCents: number; paidIds: string[] } {
  return { paidCount: orders.length, netCents: orders.reduce((sum, order) => sum + order.amountCents, 0), paidIds: [] };
}
